<?php
 namespace ehr; require_once(__DIR__ . '/../../../init.php'); require_once(__DIR__ . '/autoload.php'); interface iLogger { const LMT_INFO = 0, LMT_ERROR = 1, LMT_WARN = 2, LMT_DEBUG = 3, LMT_FATAL = 4; public function addLog(string $message, string $prefix = '', int $level = self::LMT_INFO, bool $exit = false): void; } class Logger implements iLogger { private const TIMESTAMP_FORMAT = 'Y-m-d H:s:i.u'; private const FILENAME_RECIPE = 'ehr_recipe', FILENAME_HOSPITAL = 'ehr_sick_list', FILENAME_ALL = 'ehr_all'; private $link; public function __construct(?Link $link = null) { $this->link = $link; } public function addLog(string $message, string $prefix = '', int $level = self::LMT_INFO, bool $exit = false): void { $this->writeLog($message, $prefix, $level); $this->addLinkLog($message, $level); if ($exit) { switch ($level) { case self::LMT_ERROR: exit('end'); case self::LMT_FATAL: throw new \Exception($message); } } } private function addLinkLog(string $message, int $level): void { if (empty($this->link)) { return; } $_message = $this->makeMessage($message, udate(self::TIMESTAMP_FORMAT)); $this->link->addListMessage($_message); switch ($level) { case self::LMT_INFO: Link::DEBUG && $this->link->addListMessage($_message, LINK::LOG_MSG_INFO); break; case self::LMT_ERROR: $this->link->addListMessage($_message, LINK::LOG_MSG_ERROR); break; case self::LMT_WARN: $this->link->addListMessage($_message, LINK::LOG_MSG_WARN); break; case self::LMT_DEBUG: Link::DEBUG && $this->link->addListMessage($_message, LINK::LOG_MSG_DEBUG); break; case self::LMT_FATAL: $this->link->addListMessage($_message, LINK::LOG_MSG_FATAL); break; } } private function writeLog(string $message, string $prefix = '', int $level = self::LMT_INFO): void { $file = self::FILENAME_ALL; $this->makeAppLogParam($file, $prefix); switch ($level) { case self::LMT_WARN: $_level = 1; case self::LMT_ERROR: case self::LMT_FATAL: $_level = 2; break; default: $_level = 0; } app_log((empty($prefix) ? '' : "{$prefix}: ") . $message, $_level, $file); } private function makeAppLogParam(string &$file, string &$prefix): void { if (empty($this->link)) { $type = 0; } else { $ls = $this->link->getLs(); $type = empty($ls) ? 0 : $ls->getParam('sysSetupFuncType'); } switch ($type) { case Link::SFT_RECIPE: $file = self::FILENAME_RECIPE; $prefix = $this->makePrefix('ЭР', $prefix); break; case Link::SFT_HOSPITAL: $file = self::FILENAME_HOSPITAL; $prefix = $this->makePrefix('ЭЛВН', $prefix); break; } } private function makePrefix(string $first, string $prefix): string { return $first . (empty($prefix) ? '' : " {$prefix}"); } private function makeMessage(string $message, string $datetime = ''): string { $_datetime = empty($datetime) ? udate(self::TIMESTAMP_FORMAT) : $datetime; return "\n\r{$_datetime}\t {$message}"; } } 